Definition calldata_slice_length (s : CalldataSlice) : source_length :=
   (Build_source_length (match s with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      bytes.(StatelessInputSliceFields_len)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) => bytes.(EvmMemorySliceFields_len)
   end)).

Definition stateless_input_slice_length {ex610706_ : Z} {ex610705_ : Z}
(s : StatelessInputSliceFields ex610705_ ex610706_)
(*(0 <=? ex610705_) && ((0 <=? ex610706_) && ((ex610705_ + ex610706_) <=? (2 ^ 32 - 1)))*)
: source_length :=
   (Build_source_length (s.(StatelessInputSliceFields_len))).

