(*(0 <=? off) && ((0 <=? len) && ((off + len) <=? (2 ^ 32 - 1)))*)
: StatelessInputSliceFields off len :=
   {| StatelessInputSliceFields_bytes := off;  StatelessInputSliceFields_len := len |}.

