Definition code_slice {off : Z} {len : Z} (bytes : CodeRegionSliceFields off len)
(*(0 <=? off) && ((0 <=? len) && ((off + len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? len) && ((len + 32) <=? (2 ^ 32 - 1)))*)
: CodeSlice :=
   @existT _ _ len (@existT _ _ off ((bytes : CodeRegionSliceFields off len))).

Definition validated_code_slice {ex611009_ : Z} {ex611008_ : Z}
(bytes : CodeRegionSliceFields ex611008_ ex611009_)
(*(0 <=? ex611008_) && ((0 <=? ex611009_) && ((ex611008_ + ex611009_) <=? (2 ^ 32 - 1)))*)
: M (CodeSlice) :=
   (if Z.leb (bytes.(CodeRegionSliceFields_len)) ((Z.sub ((Z.sub ((pow2 (32))) (1))) (32))) then
      returnM ((code_slice (bytes)) : {len & {off & (CodeRegionSliceFields off len)}}%type)
    else assert_exp' false "executable code cursor headroom" >>= fun _ => exit tt)
    : M ({len & {off & (CodeRegionSliceFields off len)}}%type).

Definition EMPTY_CODE_SLICE :=
(code_slice (EMPTY_CODE_REGION_SLICE))
 : {len & {off & (CodeRegionSliceFields off len)}}%type.
#[export] Hint Unfold EMPTY_CODE_SLICE : sail.
Definition undefined_DeepStackOperation '(tt : unit) : M (DeepStackOperation) :=
   (internal_pick ([DeepStackDuplicate; DeepStackSwap; DeepStackExchange; NotDeepStackOperation]))
    : M (DeepStackOperation).

Definition deep_stack_operation (opcode : opcode) (*(0 <=? opcode) && (opcode <=? 255)*)
: DeepStackOperation :=
   let opcode := (opcode).(opcode_value) in
   let l__0 := opcode in
   if Z.eqb (l__0) (230) then DeepStackDuplicate
   else if Z.eqb (l__0) (231) then DeepStackSwap
   else if Z.eqb (l__0) (232) then DeepStackExchange
   else NotDeepStackOperation.

Definition deep_stack_immediate_valid (immediate : mword 8) : bool :=
   let value : Z := uint (immediate) in
   orb ((Z.leb (value) (90))) ((Z.leb (128) (value))).

Definition exchange_immediate_valid (immediate : mword 8) : bool :=
   let value : Z := uint (immediate) in
   orb ((Z.leb (value) (81))) ((Z.leb (128) (value))).

Definition deep_stack_operation_immediate_valid
(operation : DeepStackOperation) (immediate : mword 8)
: bool :=
   match operation with
   | DeepStackDuplicate => deep_stack_immediate_valid (immediate)
   | DeepStackSwap => deep_stack_immediate_valid (immediate)
   | DeepStackExchange => exchange_immediate_valid (immediate)
   | NotDeepStackOperation => false
   end.

Definition analyzed_code {off : Z} {len : Z}
(bytes : CodeRegionSliceFields off len) (jumpdests : jump_table_index)
(*(0 <=? off) && ((0 <=? len) && ((off + len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? len) && ((len + 32) <=? (2 ^ 32 - 1)))*)
(*(0 <=? jumpdests) && (jumpdests <=? (2 ^ 64 - 1))*)
: CodeFields off len :=
   let jumpdests := (jumpdests).(jump_table_index_value) in
   {| CodeFields_bytes := bytes.(CodeRegionSliceFields_bytes);
      CodeFields_len := bytes.(CodeRegionSliceFields_len);
      CodeFields_jumpdests := (Build_jump_table_index (jumpdests)) |}.

Definition code_bytes {off : Z} {len : Z} (code : CodeFields off len)
(*(0 <=? off) && ((0 <=? len) && ((off + len) <=? (2 ^ 32 - 1))) &&
  ((0 <=? len) && ((len + 32) <=? (2 ^ 32 - 1)))*)
: CodeRegionSliceFields off len :=
   {| CodeRegionSliceFields_bytes := code.(CodeFields_bytes);
      CodeRegionSliceFields_len := code.(CodeFields_len) |}.

Definition EMPTY_CODE :=
(@existT _ _ _ (@existT _ _ _ (analyzed_code (projT2 (projT2 (EMPTY_CODE_SLICE)))
                                 (Build_jump_table_index (((EMPTY_JUMP_TABLE).(jump_table_index_value)))))))
 : {len & {off & (CodeFields off len)}}%type.
#[export] Hint Unfold EMPTY_CODE : sail.
