Definition log_store_index_increment (value : log_store_index)
(*(0 <=? value) && (value <=? (2 ^ 64 - 1))*)
: M (log_store_index) :=
   let value := (value).(log_store_index_value) in
   ((if Z.ltb (value) ((Z.sub ((pow2 (64))) (1))) then returnM ((Z.add (value) (1)))
     else assert_exp' false "log store index overflow" >>= fun _ => exit tt)
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_log_store_index (semanticResult)).

Definition log_store_index_add (left' : log_store_index) (right' : log_store_index)
(*(0 <=? left') && (left' <=? (2 ^ 64 - 1))*) (*(0 <=? right') && (right' <=? (2 ^ 64 - 1))*)
: M (log_store_index) :=
   let left' := (left').(log_store_index_value) in
   let right' := (right').(log_store_index_value) in
   ((if Z.leb (right') ((Z.sub ((Z.sub ((pow2 (64))) (1))) (left'))) then
       returnM ((Z.add (left') (right')))
     else assert_exp' false "log store index overflow" >>= fun _ => exit tt)
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_log_store_index (semanticResult)).

