(_limit : Z) (_regular_limit : Z) (tx_type : TxType) (success : bool) (gas_used : Z)
(execution_gas : Z) (state_gas : Z) (logs : LogSeriesRef)
(*(0 <=? _limit) &&
  ((_limit <=? (2 ^ 64 - 1)) &&
    ((0 <=? _regular_limit) &&
      ((_regular_limit <=? _limit) &&
        ((0 <=? gas_used) &&
