   let out : vec (mword 8) 256 := EMPTY_LOGS_BLOOM in
   (let '(loop_i_lower) := 0 in
   let '(loop_i_upper) := 255 in
   (foreach_ZM_up loop_i_lower loop_i_upper 1 out
     (fun i '(out) =>
       (stateless_input_slice_byte (reference) (i)) >>= fun (w__0 : mword 8) =>
       let out := (vec_update_dec (out) ((Z.sub (255) (i))) (w__0))  : vec (mword 8) 256 in
       returnM (out))))
    : M (vec (mword 8) 256).

Definition logs_bloom_matches_ref {ex612680_ : Z}
(computed : vec (mword 8) 256) (reference : StatelessInputSliceFields ex612680_ 256)
(ex612681_ := 256)
(*(0 <=? ex612680_) && ((0 <=? ex612681_) && ((ex612680_ + ex612681_) <=? (2 ^ 32 - 1))) &&
  (ex612681_ =? 256)*)
