    : M ({len & {off & (OutputSliceFields off len)}}%type).

Definition freeze_calldata_output (data : CalldataSlice) : M (OutputSlice) :=
   match data with
   | InputCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (freeze_input_output (bytes))  : M ({len & {off & (OutputSliceFields off len)}}%type)
   | MemoryCalldata (@existT _ _ len (@existT _ _ off bytes)) =>
      (freeze_memory_output (bytes))  : M ({len & {off & (OutputSliceFields off len)}}%type)
   end
    : M ({len & {off & (OutputSliceFields off len)}}%type).

