   (create_address (a) (Build_account_nonce ((nonce))))
    : M (vec (mword 8) 20).

Definition k_create2_addr (a : vec (mword 8) 20) (salt : word) (inithash : vec (mword 8) 32)
(*(0 <=? salt) && (salt <=? (2 ^ 256 - 1))*)
: M (address_typ) :=
