   (create2_address (a) (Build_word ((salt))) (inithash))
    : M (vec (mword 8) 20).

Definition storage_key (a : vec (mword 8) 20) (s : word) (*(0 <=? s) && (s <=? (2 ^ 256 - 1))*)
: StorageKey :=
   let s := (s).(word_value) in {| StorageKey_addr := a;  StorageKey_slot := (Build_word (s)) |}.

Definition precompile_active_at_fork (n : PrecompileId) : M (bool) :=
   read_reg k_execution_profile >>= fun '(@existT _ _ __execution_profile12 (@existT _ _ __execution_profile11 (@existT _ _ __execution_profile10 (@existT _ _ __execution_profile9 (@existT _ _ __execution_profile8 (@existT _ _ __execution_profile7 (@existT _ _ __execution_profile6 (@existT _ _ __execution_profile5 (@existT _ _ __execution_profile4 (@existT _ _ __execution_profile3 (@existT _ _ __execution_profile2 (@existT _ _ __execution_profile1 (@existT _ _ __execution_profile0 execution_profile))))))))))))) =>
   let profile := execution_profile.(ExecutionProfileFields_protocol) in
   returnM (match n with
   | NotPrecompile => false
   | Ecrecover => true
   | Sha256 => true
   | Ripemd160 => true
   | Identity => true
   | Modexp => Z.geb (profile.(ProtocolProfileFields_fork)) (Byzantium)
   | Bn254Add => Z.geb (profile.(ProtocolProfileFields_fork)) (Byzantium)
   | Bn254Mul => Z.geb (profile.(ProtocolProfileFields_fork)) (Byzantium)
   | Bn254Pairing => Z.geb (profile.(ProtocolProfileFields_fork)) (Byzantium)
   | Blake2f => Z.geb (profile.(ProtocolProfileFields_fork)) (Istanbul)
   | KzgPointEvaluation => Z.geb (profile.(ProtocolProfileFields_fork)) (Cancun)
   | BlsG1Add => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsG1Msm => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsG2Add => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsG2Msm => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsPairing => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsMapFpToG1 => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | BlsMapFp2ToG2 => Z.geb (profile.(ProtocolProfileFields_fork)) (Prague)
   | P256Verify => Z.geb (profile.(ProtocolProfileFields_fork)) (Osaka)
   end).

Definition precompile_id_if_active (candidate : PrecompileId) : M (precompile_id) :=
   (precompile_active_at_fork (candidate)) >>= fun active =>
   returnM ((if active then candidate else NotPrecompile)).

