Definition path_matches (key : TriePath) (pos : trie_path_cursor) (seg : TriePath)
(*(0 <=? pos) && (pos <=? 64)*)
: M (bool) :=
   let pos := (pos).(trie_path_cursor_value) in
   let segment_len := (path_len (seg)).(trie_path_len_value) in
   let key_len := (path_len (key)).(trie_path_len_value) in
   let stop := Z.add (pos) (segment_len) in
   (if Z.ltb (key_len) (stop) then returnM (false)
    else
      let ok : bool := true in
      let offset : Z := 0 in
      (whileMT
        (offset, ok)
        (fun '(offset, ok) => Z.sub (segment_len) (offset))
        (fun '(offset, ok) => returnM ((andb (ok) (((Z.ltb (offset) (segment_len))  : bool)))))
        (fun '(offset, ok) =>
          (assert_exp' true "loop dummy assert" >>= fun _ =>
           let key_index := Z.add (pos) (offset) in
           (if Z.leb (key_index) (64) return M (bool) then
              (path_nibble (key) (Build_trie_path_cursor ((key_index)))) >>= fun key_nibble =>
              (path_nibble (seg) (Build_trie_path_cursor ((offset)))) >>= fun segment_nibble =>
              let ok : bool :=
                if neq_vec (key_nibble) (segment_nibble) then
                  let ok : bool := false in
                  ok
                else ok in
              returnM (ok)
            else returnM (false)) >>= fun (ok : bool) =>
           let current_offset := offset in
           (if Z.ltb (current_offset) (64) then returnM ((Z.add (current_offset) (1)))
            else (fatal_error (WitnessDeficient))  : M (Z)) >>= fun (w__1 : Z) =>
           let offset := w__1  : Z in
           returnM ((offset, ok)))
           : M ((Z * bool)))) >>= fun '((offset, ok)
      : (Z * bool)) =>
      returnM (ok))
    : M (bool).

Definition resolve_witness_ref (r : NodeRef) : M (StatelessInputSlice) :=
