Definition validated_refund_add (left' : Z) (right' : Z)
(*(((- (199 * (2 ^ 64 - 1)))) <=? left') &&
  ((left' <=? (199 * (2 ^ 64 - 1))) &&
    ((((- (199 * (2 ^ 64 - 1)))) <=? right') && (right' <=? (199 * (2 ^ 64 - 1)))))*)
: M (gas_refund) :=
   (let total := Z.add (left') (right') in
   (if andb ((Z.leb ((Z.opp ((Z.mul (199) ((Z.sub ((pow2 (64))) (1))))))) (total)))
         ((Z.leb (total) ((Z.mul (199) ((Z.sub ((pow2 (64))) (1))))))) then
      returnM (total)
