Definition bls_msm_gas
(table : vec bls_discount 128) (base : gas_constant) (maxd : bls_discount) (k : source_length)
(available : gas_typ) (*(0 <=? base) && (base <=? 45000)*)
(*(0 <=? maxd) && (maxd <=? (2 ^ 16 - 1))*) (*(0 <=? k) && (k <=? (2 ^ 32 - 1))*)
(*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let table := (vec_map (fun semanticValue => (semanticValue).(bls_discount_value)) (table)) in
   let base := (base).(gas_constant_value) in
   let maxd := (maxd).(bls_discount_value) in
   let k := (k).(source_length_value) in
   let available := (available).(gas_value) in
   if Z.eqb (k) (0) then gas_charge (Build_gas_cost (((GAS_COST_ZERO).(gas_cost_value))))
   else
     let discount : Z := maxd in
     let discount : Z :=
       if Z.ltb (k) (128) then
         let index : Z := Z.sub (128) (k) in
         vec_access_dec (table) (index)
       else discount in
     let coefficient : Z := Z.mul (base) (discount) in
     let whole := e_div (k) (1000) in
     let remainder := Z.rem (k) (1000) in
     let whole_product : Z := Z.mul (coefficient) (whole) in
     if Z.gtb (whole_product) (available) then GAS_CHARGE_UNAFFORDABLE
     else
       let major : Z := whole_product in
       let tail_product : Z := Z.mul (coefficient) (remainder) in
       let tail : Z := e_div (tail_product) (1000) in
       let total : Z := Z.add (major) (tail) in
       if Z.leb (total) (available) then
         let affordable : Z := total in
         gas_charge (Build_gas_cost ((affordable)))
       else GAS_CHARGE_UNAFFORDABLE.

Definition linear_gas
(base : gas_constant) (per_unit : gas_constant) (units : source_length) (available : gas_typ)
(*(0 <=? base) && (base <=? 45000)*) (*(0 <=? per_unit) && (per_unit <=? 45000)*)
(*(0 <=? units) && (units <=? (2 ^ 32 - 1))*) (*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
: GasCharge :=
   let base := (base).(gas_constant_value) in
   let per_unit := (per_unit).(gas_constant_value) in
   let units := (units).(source_length_value) in
   let available := (available).(gas_value) in
   let variable_cost : Z := Z.mul (per_unit) (units) in
   let exact_cost : Z := Z.add (variable_cost) (base) in
   if Z.gtb (exact_cost) (available) then GAS_CHARGE_UNAFFORDABLE
   else
     let affordable : Z := exact_cost in
     gas_charge (Build_gas_cost ((affordable))).

Definition fixed_precompile_gas (cost : Z) (available : gas_typ) (*0 <=? cost*)
(*(0 <=? available) && (available <=? (2 ^ 64 - 1))*)
