Definition run_precompile_slice (num : PrecompileId) (input : CalldataSlice) : M (PrecompileResult) :=
   match num with
   | NotPrecompile => returnM ((precompile_failure (tt)))
   | Ecrecover => (run_ecrecover (input))  : M (PrecompileResult)
   | Sha256 => (run_sha256 (input))  : M (PrecompileResult)
   | Ripemd160 => (run_ripemd160 (input))  : M (PrecompileResult)
   | Identity => (copied_result (input))  : M (PrecompileResult)
   | Modexp => (run_modexp (input))  : M (PrecompileResult)
   | Bn254Add =>
      (accelerator_bn254_add (input)) >>= fun success =>
      returnM ((accelerator_result (success) (PRECOMPILE_DOUBLE_WORD_LENGTH)))
   | Bn254Mul =>
      (accelerator_bn254_mul (input)) >>= fun success =>
      returnM ((accelerator_result (success) (PRECOMPILE_DOUBLE_WORD_LENGTH)))
