       : M (PrecompileResult)
   | Blake2f => (run_blake2f (input))  : M (PrecompileResult)
   | KzgPointEvaluation => (run_kzg_point_evaluation (input))  : M (PrecompileResult)
   | BlsG1Add => (run_bls_g1_add (input))  : M (PrecompileResult)
   | BlsG1Msm => (run_bls_g1_msm (input))  : M (PrecompileResult)
   | BlsG2Add => (run_bls_g2_add (input))  : M (PrecompileResult)
   | BlsG2Msm => (run_bls_g2_msm (input))  : M (PrecompileResult)
   | BlsPairing => (run_bls_pairing (input))  : M (PrecompileResult)
   | BlsMapFpToG1 => (run_bls_map_fp_to_g1 (input))  : M (PrecompileResult)
   | BlsMapFp2ToG2 => (run_bls_map_fp2_to_g2 (input))  : M (PrecompileResult)
   | P256Verify => (run_p256_verify (input))  : M (PrecompileResult)
