Definition process_auth (au : Authorization) : M (authorization_item_refund) :=
   (let refund : Z := 0 in
   let authority := au.(Authorization_authority) in
   let chain_id_is_zero := word_is_zero ((au.(Authorization_chain_id)).(word_value)) in
   (read_reg k_chain_id) >>= fun semanticResult => returnM (semanticResult).(chain_identifier_value) >>= fun (w__0 : Z) =>
   let expected_chain_id :=
     (word_of_chain_identifier (Build_chain_identifier ((w__0)))).(chain_identifier_value) in
   let chain_id_matches := Z.eqb ((au.(Authorization_chain_id)).(word_value)) (expected_chain_id) in
   (if andb (au.(Authorization_valid_sig)) ((orb (chain_id_is_zero) (chain_id_matches)))
      return
      M (Z) then
      (k_account_mark_warm (authority)) >>
      (k_deleg_target (authority)) >>= fun '((is_deleg, _)) =>
      (k_code_key (authority)) >>= fun code_key =>
      ((k_get_nonce (authority)) >>= fun semanticResult =>
       returnM (semanticResult).(account_nonce_value)) >>= fun nonce =>
      (if andb ((orb ((generic_eq (code_key) (KECCAK_EMPTY))) (is_deleg)))
            (((Z.eqb (nonce) ((au.(Authorization_nonce)).(account_nonce_value)))
             : bool))
         return
         M (Z) then
         (k_account_exists (authority)) >>= fun existed =>
         (if generic_eq (au.(Authorization_address)) (ZERO_ADDRESS) return M (unit) then
            (k_clear_code (authority))
             : M (unit)
          else (k_set_delegation (authority) (au.(Authorization_address)))  : M (unit)) >>
         (k_bump_nonce (authority)) >>
         let refund : Z :=
           if existed then
             let refund : Z := Z.sub (PER_EMPTY_ACCOUNT) (PER_AUTH_BASE) in
             refund
           else refund in
         returnM (refund)
       else returnM (refund))
       : M (Z)
    else returnM (refund))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_authorization_item_refund (semanticResult)).

Definition authorization_refund_add
(item : authorization_item_refund) (accumulated : authorization_refund_typ)
(*(0 <=? item) && (item <=? 12500)*) (*(0 <=? accumulated) && (accumulated <=? (12500 * 2 ^ 30))*)
: M (authorization_refund_typ) :=
   let item := (item).(authorization_item_refund_value) in
   let accumulated := (accumulated).(authorization_refund_value) in
   (let bound := Z.mul (12500) ((pow2 (30))) in
   (if Z.leb (accumulated) ((Z.sub (bound) (item))) then returnM ((Z.add (item) (accumulated)))
    else (fatal_error (ExecutionInvalid))  : M (Z))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_authorization_refund_typ (semanticResult)).

Fixpoint _rec_process_auth_cursor
(authorizations : PreparedAuthorizationList) (count : prepared_authorization_count) (_reclimit : Z)
(*(0 <=? count) && (count <=? (e_div (2 ^ 24) 7816))*) (_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (authorization_refund_typ).
exact (
   let count := (count).(prepared_authorization_count_value) in
   (assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
    (if Z.eqb (count) (0) then returnM (0)
     else
       (prepared_authorization_head (authorizations)) >>= fun authorization =>
       (prepared_authorization_tail (authorizations) (count)) >>= fun remaining =>
       ((process_auth (authorization)) >>= fun semanticResult =>
        returnM (semanticResult).(authorization_item_refund_value)) >>= fun item_refund =>
       ((_rec_process_auth_cursor (remaining)
           (Build_prepared_authorization_count (((Z.sub (count) (1))))) ((Z.sub (_reclimit) (1)))
           (_limit_reduces_bool _acc ltac:(assumption))) >>= fun semanticResult =>
        returnM (semanticResult).(authorization_refund_value)) >>= fun remaining_refund =>
       ((authorization_refund_add (Build_authorization_item_refund ((item_refund)))
           (Build_authorization_refund_typ ((remaining_refund)))) >>= fun semanticResult =>
        returnM (semanticResult).(authorization_refund_value))
        : M (Z))
     : M (Z)) >>= fun semanticResult =>
   returnM (Build_authorization_refund_typ (semanticResult))
).
Defined.


Definition process_auth_cursor
(authorizations : PreparedAuthorizationList) (count : prepared_authorization_count)
(*(0 <=? count) && (count <=? (e_div (2 ^ 24) 7816))*)
: M (authorization_refund_typ) :=
