        ((count
         : Z)) (Zwf_guarded _)) >>= fun semanticResult =>
     returnM (semanticResult).(authorization_refund_value))
    : M (Z)) >>= fun semanticResult =>
   returnM (Build_authorization_refund_typ (semanticResult)).

Definition process_auth_list (authorizations : PreparedAuthorizationList)
