Definition process_amsterdam_auth
(au : Authorization) (sender : vec (mword 8) 20) (current_target : vec (mword 8) 20)
(transfers_value : bool) (carried_gas : gas_typ) (carried_state_gas : state_gas_typ)
(carried_state_spill : state_gas_spill) (*(0 <=? carried_gas) && (carried_gas <=? (2 ^ 64 - 1))*)
(*(0 <=? carried_state_gas) && (carried_state_gas <=? (2 ^ 64 - 1))*)
(*(0 <=? carried_state_spill) && (carried_state_spill <=? (2 ^ 24))*)
: M ((bool * gas_typ * state_gas_typ * state_gas_spill)) :=
   let carried_gas := (carried_gas).(gas_value) in
   let carried_state_gas := (carried_state_gas).(state_gas_value) in
   let carried_state_spill := (carried_state_spill).(state_gas_spill_value) in
   catch_early_return
     ((let gas_after : Z := carried_gas in
     let state_gas_after : Z := carried_state_gas in
     let state_spill_after : Z := carried_state_spill in
     let authority := au.(Authorization_authority) in
     let chain_id_is_zero := word_is_zero ((au.(Authorization_chain_id)).(word_value)) in
     liftR ((read_reg k_chain_id) >>= fun semanticResult =>
     returnM (semanticResult).(chain_identifier_value)) >>= fun (w__0 : Z) =>
     let expected_chain_id :=
       (word_of_chain_identifier (Build_chain_identifier ((w__0)))).(chain_identifier_value) in
     let chain_id_matches := Z.eqb ((au.(Authorization_chain_id)).(word_value)) (expected_chain_id) in
     (if andb (au.(Authorization_valid_sig)) ((orb (chain_id_is_zero) (chain_id_matches)))
        return
        MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) ((Z * Z * Z)) then
        liftR ((k_account_mark_warm (authority))) >>
        liftR ((k_deleg_target (authority))) >>= fun '((currently_delegated, _)) =>
        liftR ((k_code_key (authority))) >>= fun code_key =>
        liftR (((k_get_nonce (authority)) >>= fun semanticResult =>
                returnM (semanticResult).(account_nonce_value))) >>= fun nonce =>
        (if andb ((orb ((generic_eq (code_key) (KECCAK_EMPTY))) (currently_delegated)))
              (((Z.eqb (nonce) ((au.(Authorization_nonce)).(account_nonce_value)))
               : bool))
           return
           MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) ((Z * Z * Z)) then
           liftR ((authorization_tracker_seen (authority))) >>= fun seen =>
           (if seen return MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (bool) then
              liftR ((authorization_tracker_originally_delegated (authority)))
               : MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (bool)
