           let already_written :=
             orb (seen)
               ((orb ((generic_eq (authority) (sender)))
                   ((andb (transfers_value) ((generic_eq (authority) (current_target))))))) in
           liftR ((k_account_exists (authority))) >>= fun account_exists =>
           let account_missing := negb (account_exists) in
