              let state_spill_after : Z := next_state_spill in
              (if state_gas_halt
                 return
                 MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (unit) then
                 (early_return (let '(semanticValue0, semanticValue1, semanticValue2, semanticValue3) := (false,
                                                                                                          gas_after,
                                                                                                          state_gas_after,
                                                                                                          state_spill_after) in (semanticValue0, (Build_gas_typ (semanticValue1)), (Build_state_gas_typ (semanticValue2)), (Build_state_gas_spill (semanticValue3)))) :
                   MR (bool * gas_typ * state_gas_typ * state_gas_spill) unit)
                  : MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (unit)
