                                                                                                          gas_after,
                                                                                                          state_gas_after,
                                                                                                          state_spill_after) in (semanticValue0, (Build_gas_typ (semanticValue1)), (Build_state_gas_typ (semanticValue2)), (Build_state_gas_spill (semanticValue3)))) :
                   MR (bool * gas_typ * state_gas_typ * state_gas_spill) unit)
                  : MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (unit)
               else returnR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (tt)) >>
              returnR ((bool * gas_typ * state_gas_typ * state_gas_spill)) ((gas_after, state_gas_after, state_spill_after))
            else
              returnR ((bool * gas_typ * state_gas_typ * state_gas_spill)) ((gas_after, state_gas_after, state_spill_after))) >>= fun '((gas_after, state_gas_after, state_spill_after)
           : (Z * Z * Z)) =>
           (if generic_eq (au.(Authorization_address)) (ZERO_ADDRESS)
              return
              MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (unit) then
              liftR ((k_clear_code (authority)))
               : MR ((bool * gas_typ * state_gas_typ * state_gas_spill)) (unit)
            else
              liftR ((k_set_delegation (authority) (au.(Authorization_address))))
