Definition merge_ext_node {ex616170_ : Z} {ex616169_ : Z}
(prefix : TriePath) (childnode : StatelessInputSliceFields ex616169_ ex616170_)
(*(0 <=? ex616169_) && ((0 <=? ex616170_) && ((ex616169_ + ex616170_) <=? (2 ^ 32 - 1)))*)
: M (NodeRef) :=
