       : M (NodeRef))
    : M (NodeRef).

Definition merge_ext_ref (prefix : TriePath) (childref : NodeRef) : M (NodeRef) :=
   let prefix_length := (path_len (prefix)).(trie_path_len_value) in
   (if Z.eqb (prefix_length) (0) then returnM (childref)
