         | InputExtensionNode (path, child) =>
            (path_concat (prefix) (path)) >>= fun merged_path =>
            (extension_child_ref (merged_path) (child))
             : M (NodeRef)
         | _ => (extension_child_ref (prefix) (childref))  : M (NodeRef)
