          : M (NodeRef)
      | ScratchInlineRef node =>
         (inline_node_slice (node)) >>= fun '(@existT _ _ __node_slice1 (@existT _ _ __node_slice0 node_slice)) =>
         (decode_scratch_trie_node (node_slice)) >>= fun decoded =>
         match decoded with
         | ScratchLeafNode (path, @existT _ _ __node_slice1 (@existT _ _ __node_slice0 value)) =>
            (path_concat (prefix) (path)) >>= fun merged_path =>
            (scratch_leaf_child_ref (merged_path) (value))
             : M (NodeRef)
