Definition encode_state_account (info : AccountInfo) (storage_root : vec (mword 8) 32)
: M (ScratchSlice) :=
   let nonce_length := rlp_uint_word_size ((info.(AccountInfo_nonce)).(account_nonce_value)) in
   let balance_length := rlp_uint_word_size ((info.(AccountInfo_balance)).(word_value)) in
   let storage_root_length := rlp_word_size (tt) in
   let code_hash_length := rlp_word_size (tt) in
   let content_len :=
     Z.add ((Z.add ((Z.add (nonce_length) (balance_length))) (storage_root_length)))
       (code_hash_length) in
   (rlp_list_size (content_len)) >>= fun encoded_length =>
   (rlp_encoder_begin (encoded_length)) >>= fun encoder =>
   (rlp_write_list_prefix (content_len)) >>
   (rlp_write_uint_word ((info.(AccountInfo_nonce)).(account_nonce_value))) >>
   (rlp_write_uint_word ((info.(AccountInfo_balance)).(word_value))) >>
   let storage_root_word := (hash_to_word (storage_root)).(word_value) in
   (rlp_write_word (Build_word ((storage_root_word)))) >>
   let code_hash_word := (hash_to_word (info.(AccountInfo_code_hash))).(word_value) in
   (rlp_write_word (Build_word ((code_hash_word)))) >>
   (rlp_encoder_finish (encoder))
    : M ({len & {off & (ScratchSliceFields off len)}}%type).

Definition account_update (trie_entry : AcctTrieEntry) (storage_root : vec (mword 8) 32)
: M (TrieUpdate) :=
   let entry := trie_entry.(AcctTrieEntry_entry) in
   let current := entry.(AcctEntry_value).(AcctValue_curr) in
   let key := path_new (trie_entry.(AcctTrieEntry_address_hash)) (Build_trie_path_len ((64))) in
   let account_absent := negb (current.(Account_present)) in
   let account_empty := account_info_empty (current.(Account_info)) in
   (if orb (account_absent) (account_empty) then
      returnM (({| TrieUpdate_key := key;  TrieUpdate_change := TrieDelete (tt) |}))
    else
      (encode_state_account (current.(Account_info)) (storage_root)) >>= fun '(@existT _ _ __encoded_account1 (@existT _ _ __encoded_account0 encoded_account)) =>
      returnM (({| TrieUpdate_key := key;
                   TrieUpdate_change := TriePut (@existT _ _ _ (@existT _ _ _ (encoded_account))) |})))
    : M (TrieUpdate).

Definition account_value_changed (value : AcctValue) : bool :=
   orb
     ((negb
         ((Z.eqb ((value.(AcctValue_curr).(Account_info).(AccountInfo_nonce)).(account_nonce_value))
             ((value.(AcctValue_orig).(Account_info).(AccountInfo_nonce)).(account_nonce_value))))))
     (((orb
          ((negb
              ((Z.eqb ((value.(AcctValue_curr).(Account_info).(AccountInfo_balance)).(word_value))
                  ((value.(AcctValue_orig).(Account_info).(AccountInfo_balance)).(word_value))))))
          ((orb
              ((negb
                  ((generic_eq (value.(AcctValue_curr).(Account_info).(AccountInfo_storage_root))
                      (value.(AcctValue_orig).(Account_info).(AccountInfo_storage_root))))))
              ((orb
                  ((negb
                      ((generic_eq (value.(AcctValue_curr).(Account_info).(AccountInfo_code_hash))
                          (value.(AcctValue_orig).(Account_info).(AccountInfo_code_hash))))))
                  ((orb
                      ((negb
                          ((Bool.eqb (value.(AcctValue_curr).(Account_present))
                              (value.(AcctValue_orig).(Account_present))))))
                      ((negb
                          ((Bool.eqb (value.(AcctValue_curr).(Account_storage_cleared))
                              (value.(AcctValue_orig).(Account_storage_cleared)))))))))))))
      : bool)).

Definition trie_child_ref (it : TrieItem) (depth : trie_path_len)
(*(0 <=? depth) && (depth <=? 64)*)
: M (NodeRef) :=
   let depth := (depth).(trie_path_len_value) in
   (path_drop (it.(TrieItem_path)) (Build_trie_path_len ((depth)))) >>= fun suffix =>
   let suffix_len := (path_len (suffix)).(trie_path_len_value) in
   match it.(TrieItem_value) with
   | EmptySubtree tt => returnM ((EmptyRef (tt)))
   | LeafItem value => (leaf_child_ref (suffix) (value))  : M (NodeRef)
   | BranchItem subref =>
      (if Z.eqb (suffix_len) (0) then returnM (subref)
       else (merge_ext_ref (suffix) (subref))  : M (NodeRef))
       : M (NodeRef)
   | SubtreeItem subref =>
      (if Z.eqb (suffix_len) (0) then returnM (subref)
       else
         match subref with
         | HashRef h =>
            (node_db_lookup (h)) >>= fun '(@existT _ _ __node1 (@existT _ _ __node0 node)) =>
            (if Z.eqb (node.(StatelessInputSliceFields_len)) (0) return M (NodeRef) then
               (fatal_error (WitnessDeficient))
                : M (NodeRef)
             else (merge_ext_node (suffix) (node))  : M (NodeRef))
             : M (NodeRef)
         | _ => (merge_ext_ref (suffix) (subref))  : M (NodeRef)
         end
          : M (NodeRef))
       : M (NodeRef)
   end
    : M (NodeRef).

