Definition trie_children_add
(children : TrieChildren) (prefix : TriePath) (index : mword 4) (child : TrieItem)
: M (TrieChildren) :=
   match child.(TrieItem_value) with
   | EmptySubtree tt => returnM (children)
   | _ =>
      let depth := (path_len (prefix)).(trie_path_len_value) in
      let child_count := children.(TrieChildren_count) in
      (if Z.ltb (depth) (64) then returnM ((Z.add (depth) (1)))
       else (fatal_error (WitnessDeficient))  : M (Z)) >>= fun (child_depth : Z) =>
      (if Z.ltb (child_count) (16) then returnM ((Z.add (child_count) (1)))
       else (fatal_error (WitnessDeficient))  : M (Z)) >>= fun (next_child_count : Z) =>
      (path_single (index)) >>= fun child_segment =>
      (path_concat (prefix) (child_segment)) >>= fun child_prefix =>
      (path_prefix_of (child_prefix) (child.(TrieItem_path))) >>= fun path_below_child =>
      let path_outside_child := negb (path_below_child) in
      (if path_outside_child return M (unit) then (fatal_error (WitnessDeficient))  : M (unit)
       else returnM (tt)) >>
      let child_already_present := branch_mask_has (children.(TrieChildren_mask)) (index) in
      (if child_already_present return M (unit) then (fatal_error (WitnessDeficient))  : M (unit)
       else returnM (tt)) >>
      let updated := children in
      let updated : TrieChildren :=
        {[ updated with TrieChildren_mask := branch_mask_set (updated.(TrieChildren_mask)) (index) ]} in
      (trie_child_ref (child) (Build_trie_path_len ((child_depth)))) >>= fun (w__2 : NodeRef) =>
      let updated :=
        {[ updated with
          TrieChildren_children :=
            vec_update_dec (updated.(TrieChildren_children)) ((uint (index))) (w__2) ]}
         : TrieChildren in
      let updated : TrieChildren := {[ updated with TrieChildren_only := child ]} in
      let updated : TrieChildren := {[ updated with TrieChildren_count := next_child_count ]} in
      returnM (updated)
   end
    : M (TrieChildren).

