                      TrieUpdateCursor_current := updates.(TrieUpdateCursor_current);
                      TrieUpdateCursor_relation := UpdateUnderPrefix (path_postfix) |}))
       else returnM (updates))
       : M (TrieUpdateCursor)
   end
    : M (TrieUpdateCursor).

