    : M (Z).

Definition overlay_child_ranges_remaining
(updates : TrieUpdateCursor) (existing_pending : bool) (existing_nibble : mword 4)
: M (Z) :=
   let update_pending := update_under_current_prefix (updates) in
   (if update_pending return M (Z) then
      (update_child_nibble (updates)) >>= fun child_nibble => returnM ((uint (child_nibble)))
    else returnM (16)) >>= fun (update_position : Z) =>
