        let amount :=
          (word_of_withdrawal_amount
             (Build_withdrawal_amount (((withdrawal.(Withdrawal_amount)).(withdrawal_amount_value))))).(withdrawal_amount_value) in
        let amount_in_wei := alu_mul (amount) (1000000000) in
