Definition htr_leaf_capacity (depth : htr_depth) (*(0 <=? depth) && (depth <=? 25)*)
: htr_leaf_count :=
   let depth := (depth).(htr_depth_value) in
   (Build_htr_leaf_count (let l__0 := depth in
   if Z.eqb (l__0) (0) then 1
   else if Z.eqb (l__0) (1) then 2
   else if Z.eqb (l__0) (2) then 4
   else if Z.eqb (l__0) (3) then 8
   else if Z.eqb (l__0) (4) then 16
   else if Z.eqb (l__0) (5) then 32
   else if Z.eqb (l__0) (6) then 64
   else if Z.eqb (l__0) (7) then 128
   else if Z.eqb (l__0) (8) then 256
   else if Z.eqb (l__0) (9) then 512
   else if Z.eqb (l__0) (10) then 1024
   else if Z.eqb (l__0) (11) then 2048
   else if Z.eqb (l__0) (12) then 4096
   else if Z.eqb (l__0) (13) then 8192
   else if Z.eqb (l__0) (14) then 16384
   else if Z.eqb (l__0) (15) then 32768
   else if Z.eqb (l__0) (16) then 65536
   else if Z.eqb (l__0) (17) then 131072
   else if Z.eqb (l__0) (18) then 262144
   else if Z.eqb (l__0) (19) then 524288
   else if Z.eqb (l__0) (20) then 1048576
   else if Z.eqb (l__0) (21) then 2097152
   else if Z.eqb (l__0) (22) then 4194304
   else if Z.eqb (l__0) (23) then 8388608
   else if Z.eqb (l__0) (24) then 16777216
   else 33554432)).

Fixpoint _rec_merkleize_vector_subtree {n : Z}
(leaves : vec (vec (mword 8) 32) n) (start : Z) (count : htr_leaf_count) (depth : htr_depth)
(_reclimit : Z) (*(1 <=? n) && ((n <=? 32) && (0 <=? start))*)
(*(0 <=? count) && (count <=? 33554432)*) (*(0 <=? depth) && (depth <=? 25)*)
(_acc : Acc (Zwf 0) _reclimit)
{struct _acc} : M (hash).
exact (
   let count := (count).(htr_leaf_count_value) in
   let depth := (depth).(htr_depth_value) in
   assert_exp' (Z.geb (_reclimit) (0)) "recursion limit reached" >>= fun _ =>
   (if Z.eqb (count) (0) then returnM ((ssz_zero_hash (Build_htr_depth ((depth)))))
    else if Z.eqb (depth) (0) return M (vec (mword 8) 32) then
      let leaves_length := vec_length (leaves) in
      (if andb ((Z.eqb (count) (1))) ((Z.ltb (start) n)) then
         returnM ((vec_access_dec (leaves) ((Z.sub ((Z.sub n (1))) (start)))))
       else (fatal_error (WitnessDeficient))  : M (vec (mword 8) 32))
       : M (vec (mword 8) 32)
    else
      let child_depth : Z := Z.sub (depth) (1) in
      let half := (htr_leaf_capacity (Build_htr_depth ((child_depth)))).(htr_leaf_count_value) in
      let left_count : Z := if Z.ltb (count) (half) then count else half in
      let right_count : Z := if Z.ltb (count) (half) then 0 else Z.sub (count) (half) in
      (_rec_merkleize_vector_subtree _ (leaves) (start) (Build_htr_leaf_count ((left_count)))
         (Build_htr_depth ((child_depth))) ((Z.sub (_reclimit) (1)))
         (_limit_reduces_bool _acc ltac:(assumption))) >>= fun left_root =>
      (_rec_merkleize_vector_subtree _ (leaves) ((Z.add (start) (half)))
         (Build_htr_leaf_count ((right_count))) (Build_htr_depth ((child_depth)))
         ((Z.sub (_reclimit) (1))) (_limit_reduces_bool _acc ltac:(assumption))) >>= fun right_root =>
      (sha256_pair (left_root) (right_root))
       : M (vec (mword 8) 32))
    : M (vec (mword 8) 32)
).
Defined.


Definition merkleize_vector_subtree {n : Z}
(leaves : vec (vec (mword 8) 32) n) (start : Z) (count : htr_leaf_count) (depth : htr_depth)
(*(1 <=? n) && ((n <=? 32) && (0 <=? start))*) (*(0 <=? count) && (count <=? 33554432)*)
(*(0 <=? depth) && (depth <=? 25)*)
: M (hash) :=
   let count := (count).(htr_leaf_count_value) in
   let depth := (depth).(htr_depth_value) in
   (_rec_merkleize_vector_subtree (leaves) (start) (Build_htr_leaf_count ((count)))
      (Build_htr_depth ((depth))) ((depth  : Z)) (Zwf_guarded _))
    : M (vec (mword 8) 32).

Definition merkleize {n : Z} (leaves : vec (vec (mword 8) 32) n) (depth : htr_depth)
(*(1 <=? n) && (n <=? 32)*) (*(0 <=? depth) && (depth <=? 25)*)
: M (hash) :=
   let depth := (depth).(htr_depth_value) in
   let count : Z := vec_length (leaves) in
   let capacity := (htr_leaf_capacity (Build_htr_depth ((depth)))).(htr_leaf_count_value) in
   (if Z.leb (count) (capacity) return M (vec (mword 8) 32) then
      (merkleize_vector_subtree (leaves) (0) (Build_htr_leaf_count ((count)))
         (Build_htr_depth ((depth))))
       : M (vec (mword 8) 32)
    else (fatal_error (WitnessDeficient))  : M (vec (mword 8) 32))
    : M (vec (mword 8) 32).

